    pub fn my_start_element(&mut self, element: i32, attrs: &SUMOSAXAttributes) {
        match element {
            SUMO_TAG_TLLOGIC => {
                let cur = self.myCurrentTL;
                self.myCurrentTL = self.init_traffic_light_logic(attrs, cur);
            }
            SUMO_TAG_PHASE => {
                if !self.myCurrentTL.is_null() {
                    if self.myResetPhases {
                        self.myCurrentTL.m().get_logic().m().reset_phases();
                        self.myResetPhases = false;
                    }
                    NIImporter_SUMO::add_phase(attrs, self.myCurrentTL);
                    self.myCurrentTL.m().phases_loaded();
                }
            }
            SUMO_TAG_CONNECTION => {
                self.add_tl_connection(attrs);
            }
            SUMO_TAG_DEL => {
                self.remove_tl_connection(attrs);
            }
            SUMO_TAG_PARAM => {
                if !self.myCurrentTL.is_null() {
                    let mut ok = true;
                    let key: String = attrs.get::<String>(SUMO_ATTR_KEY, "", &mut ok, true);
                    // circumventing empty string test
                    let val: String = if attrs.has_attribute(SUMO_ATTR_VALUE) { attrs.get_string(SUMO_ATTR_VALUE) } else { String::new() };
                    self.myCurrentTL.m().base.base2.set_parameter(&key, &val);
                }
            }
            _ => {}
        }
    }

