    #[allow(unused_variables)]
    pub fn init_traffic_light_logic(&mut self, attrs: &SUMOSAXAttributes, currentTL: Ptr<NBLoadedSUMOTLDef>) -> Ptr<NBLoadedSUMOTLDef> {
        if !currentTL.is_null() {
            write_error(&tlf!("Definition of tlLogic '%' was not finished.", currentTL.base.base.get_id().to_string()));
            return Ptr::null();
        }
        let mut ok = true;
        let id: String = attrs.get::<String>(SUMO_ATTR_ID, "", &mut ok, true);
        let programID: String = attrs.get_opt::<String>(SUMO_ATTR_PROGRAMID, &id, &mut ok, "UNKNOWN_PROGRAM".to_string(), true);
        let offset: SUMOTime = attrs.get_opt_offset_reporting(SUMO_ATTR_OFFSET, &id, &mut ok, 0, true);
        let typeS: String = attrs.get_opt::<String>(SUMO_ATTR_TYPE, "", &mut ok, utils::options::options_cont::get_string("tls.default-type"), true);
        let type_: TrafficLightType = if TrafficLightTypes.has_string(&typeS) {
            TrafficLightTypes.get(&typeS).unwrap_or_else(|e| panic!("{}", e))
        } else {
            write_error(&tlf!("Unknown traffic light type '%' for tlLogic '%'.", typeS, id));
            return Ptr::null();
        };
        // there are three scenarios to consider
        // 1) the tll.xml is loaded to update traffic lights defined in a net.xml:
        //   simply retrieve the loaded definitions and update them
        // 2) the tll.xml is loaded to define new traffic lights
        //   nod.xml will have triggered building of NBOwnTLDef. Replace it with NBLoadedSUMOTLDef
        // 3) the tll.xml is loaded to define new programs for a defined traffic light
        //   there should be a definition with the same id but different programID
        let programs = self.myTLLCont.get_programs(&id).clone();
        if programs.is_empty() {
            if !self.myIgnoreUnknown {
                write_error(&tlf!("Cannot load traffic light program for unknown id '%', programID '%'.", id, programID));
            }
            return Ptr::null();
        }
        // arbitrary for our purpose (first key of the std::map, i.e. smallest programID)
        let existingProgram: String = programs.keys().next().unwrap().clone();
        let mut loadedDef: Ptr<NBLoadedSUMOTLDef> = loaded_tl_def(self.myTLLCont.get_definition(&id, &programID));
        if loadedDef.is_null() {
            let oldDef: Ptr<NBLoadedSUMOTLDef> = loaded_tl_def(self.myTLLCont.get_definition(&id, &existingProgram));
            if oldDef.is_null() {
                // case 2
                // shortcut: C++ dynamic_cast<NBOwnTLDef*> cannot be checked (no runtime type tag on NBTrafficLightDefinition); a non-null default program is taken to be the NBOwnTLDef, which is the only case that reaches case 2 while loaded_tl_def reports nothing as loaded; upgrade when a type tag is added
                let newDef: Ptr<NBTrafficLightDefinition> = self.myTLLCont.get_definition(&id, DEFAULT_PROGRAM_ID);
                if newDef.is_null() {
                    write_error(&tlf!("Cannot load traffic light program for unknown id '%', programID '%'.", id, programID));
                    return Ptr::null();
                }
                let deleteDefault = true;
                loadedDef = Ptr::from_raw(Box::into_raw(Box::new(NBLoadedSUMOTLDef::new(&id, &programID, offset, type_))));
                // copy nodes and controlled inner edges
                for &n in newDef.get_nodes() {
                    loadedDef.m().add_node(n);
                }
                loadedDef.m().add_controlled_inner_edges(&newDef.get_controlled_inner_edges());
                if deleteDefault {
                    // make a copy because the vector is modified in the loop
                    let nodes: Vec<Ptr<NBNode>> = newDef.get_nodes().clone();
                    // replace default Program
                    for n in nodes {
                        n.m().remove_traffic_light(newDef);
                    }
                    self.myTLLCont.m().remove_program(id.clone(), DEFAULT_PROGRAM_ID.to_string(), true);
                }
                self.myTLLCont.m().insert(Ptr::from_mut(&mut loadedDef.m().base), false);
            } else {
                // case 3
                let oldLogic: Ptr<NBTrafficLightLogic> = oldDef.m().get_logic();
                let newLogic = NBTrafficLightLogic::new(&id, &programID, oldLogic.m().get_num_links(), offset, type_);
                loadedDef = Ptr::from_raw(Box::into_raw(Box::new(NBLoadedSUMOTLDef::new_2(&oldDef.base, &newLogic))));
                // copy nodes
                let nodes: Vec<Ptr<NBNode>> = oldDef.get_nodes().clone();
                for n in nodes {
                    loadedDef.m().add_node(n);
                }
                self.myTLLCont.m().insert(Ptr::from_mut(&mut loadedDef.m().base), false);
            }
        } else {
            // case 1
            if attrs.has_attribute(SUMO_ATTR_OFFSET) {
                loadedDef.m().set_offset(offset);
            }
            if attrs.has_attribute(SUMO_ATTR_TYPE) {
                loadedDef.m().set_type(type_);
            }
        }
        if ok {
            self.myResetPhases = true;
            self.mySeenIDs.insert(id);
            loadedDef
        } else {
            Ptr::null()
        }
    }

