    //                                    + tlID + "' (program '" + it->first + "')");
    //             }
    //         }
    //     }
    // }
    #[allow(unused_variables)]
    pub fn remove_tl_connection(&mut self, attrs: &SUMOSAXAttributes) {
        let mut ok = true;
        let tlID: String = attrs.get::<String>(SUMO_ATTR_TLID, "", &mut ok, true);
        // does the traffic light still exist?
        let programs = self.myTLLCont.get_programs(&tlID).clone();
        if programs.len() > 0 {
            // parse identifying attributes
            let from: Ptr<NBEdge> = self.retrieve_edge(attrs, SUMO_ATTR_FROM, &mut ok);
            let to: Ptr<NBEdge> = self.retrieve_edge(attrs, SUMO_ATTR_TO, &mut ok);
            let mut fromLane: i32 = -1;
            let mut toLane: i32 = -1;
            if ok {
                fromLane = self.retrieve_lane_index(attrs, SUMO_ATTR_FROM_LANE, from, &mut ok, true);
                toLane = self.retrieve_lane_index(attrs, SUMO_ATTR_TO_LANE, to, &mut ok, true);
            }
            let tlIndex: i32 = attrs.get::<i32>(SUMO_ATTR_TLLINKINDEX, "", &mut ok, true);

            let conn = NBConnection::new_2(from, fromLane, to, toLane, tlIndex, INVALID_TL_INDEX);
            // remove the connection from all definitions
            for (progID, def) in programs.iter() {
                let tlDef: Ptr<NBLoadedSUMOTLDef> = loaded_tl_def(*def);
                if !tlDef.is_null() {
                    tlDef.m().remove_connection(&conn, false);
                } else {
                    panic!("{}", ProcessError::new(tlf!("Corrupt traffic light definition '%' (program '%')", tlID, progID)));
                }
            }
        }
    }

