    #[allow(unused_variables)]
    pub fn retrieve_edge(&mut self, attrs: &SUMOSAXAttributes, attr: SumoXMLAttr, ok: &mut bool) -> Ptr<NBEdge> {
        let edgeID: String = attrs.get::<String>(attr, "", ok, true);
        let edge: Ptr<NBEdge> = self.myEdgeCont.retrieve(&edgeID, true);
        if edge.is_null() {
            write_error(&tlf!("Unknown edge '%' given in connection.", edgeID));
            *ok = false;
        }
        edge
    }

