    #[allow(unused_variables)]
    pub fn retrieve_lane_index(&mut self, attrs: &SUMOSAXAttributes, attr: SumoXMLAttr, edge: Ptr<NBEdge>, ok: &mut bool, isDelete: bool) -> i32 {
        let laneIndex: i32 = attrs.get::<i32>(attr, "", ok, true);
        if edge.get_num_lanes() <= laneIndex {
            if !isDelete {
                write_error(&tlf!("Invalid lane index '%' for edge '%'.", laneIndex.to_string(), edge.base.get_id().to_string()));
            }
            *ok = false;
        }
        laneIndex
    }

